files.content:
:root {
  --bg: #1b1b2f;
  --panel: #2e2e4f;
  --accent: #f6c445;
  --text: #f2f2f7;
  --shadow: #0d0d17;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: var(--bg);
  background-image:
    linear-gradient(var(--shadow) 1px, transparent 1px),
    linear-gradient(90deg, var(--shadow) 1px, transparent 1px);
  background-size: 24px 24px;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
}

.board {
  width: 100%;
  max-width: 420px;
  padding: 32px 24px;
  background: var(--panel);
  border: 4px solid var(--shadow);
  box-shadow: 0 0 0 4px var(--accent), 8px 8px 0 var(--shadow);
  text-align: center;
}

.title {
  margin: 0 0 24px;
  font-size: 1.5rem;
  letter-spacing: 4px;
  color: var(--accent);
}

.count {
  display: block;
  margin: 0 0 32px;
  padding: 16px 8px;
  font-size: 4rem;
  font-weight: 700;
  line-height: 1;
  color: var(--text);
  background: var(--bg);
  border: 4px solid var(--shadow);
  overflow-wrap: anywhere;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
}

.btn {
  flex: 1 1 100px;
  min-height: 56px;
  padding: 12px;
  font-family: inherit;
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--shadow);
  background: var(--accent);
  border: 4px solid var(--shadow);
  box-shadow: 4px 4px 0 var(--shadow);
  cursor: pointer;
  transition: transform 0.05s, box-shadow 0.05s, background 0.1s;
}

.btn:hover { background: #ffd966; }

.btn:focus-visible {
  outline: 4px solid var(--text);
  outline-offset: 4px;
}

.btn:active {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 var(--shadow);
}

.reset {
  background: var(--text);
  color: var(--shadow);
}

.reset:hover { background: #ffffff; }

@media (max-width: 360px) {
  .board { padding: 24px 16px; }
  .count { font-size: 3rem; }
  .btn { flex: 1 1 100%; }
}

"use strict";

(function () {
  var countEl = document.getElementById("count");
  var increaseBtn = document.getElementById("increase");
  var decreaseBtn = document.getElementById("decrease");
  var resetBtn = document.getElementById("reset");

  var count = 0;

  function render() {
    countEl.textContent = String(count);
  }

  increaseBtn.addEventListener("click", function () {
    count += 1;
    render();
  });

  decreaseBtn.addEventListener("click", function () {
    count -= 1;
    render();
  });

  resetBtn.addEventListener("click", function () {
    count = 0;
    render();
  });

  render();
})();
